create table t1(a integer primary key, b text);
with recursive n(i) as (select 1 union all select i+1 from n where i < 3000) insert into t1(b) select 'value number ' || i from n;
create index t1b on t1(b);
select backup_to('bk_dest.db', 5);
attach 'bk_dest.db' as d;
select count(*), sum(a) from d.t1;
pragma d.integrity_check;
select name from d.sqlite_schema order by name;
detach d;
pragma page_size = 1024;
vacuum;
select backup_to('bk_dest.db', -1);
attach 'bk_dest.db' as d;
pragma d.page_size;
select count(*) from d.t1;
pragma d.integrity_check;
detach d;
select backup_to('bk_dest.db', 1);
select backup_to('bk_dest.db', 1000000);
